const views=[...document.querySelectorAll('.view')];const nav=[...document.querySelectorAll('[data-view]')];function show(id){views.forEach(v=>v.classList.toggle('active',v.id===id));nav.forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}nav.forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));document.querySelectorAll('[data-view-jump]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.viewJump)));
const times=['7:00 PM','7:30 PM','8:00 PM','8:30 PM'];const rooms=[1,2,3,4];const states={"7:00 PM":['busy','open','open','busy'],"7:30 PM":['busy','open','selected','open'],"8:00 PM":['busy','open','open','open'],"8:30 PM":['open','busy','open','open']};const labels={busy:'Occupied',open:'Open',selected:'Selected'};const grid=document.getElementById('roomGrid');times.forEach(t=>{const time=document.createElement('div');time.className='time-cell';time.textContent=t;grid.appendChild(time);rooms.forEach((room,i)=>{const state=states[t][i];const cell=document.createElement('button');cell.type='button';cell.className=`slot ${state}`;cell.innerHTML=`<span class="room-no">R${room}</span><strong>${labels[state]}</strong><small>${state==='open'?'Tap to reserve':state==='selected'?'7:30 PM start':'In use'}</small>`;if(state!=='busy')cell.addEventListener('click',()=>{document.querySelectorAll('.slot.selected').forEach(x=>{x.classList.remove('selected');x.classList.add('open');x.querySelector('strong').textContent='Open';x.querySelector('small').textContent='Tap to reserve'});cell.classList.remove('open');cell.classList.add('selected');cell.querySelector('strong').textContent='Selected';cell.querySelector('small').textContent=`${t} start`;document.querySelector('.booking-card h2').textContent=`Room ${room}`;document.querySelector('.range strong').textContent=`${t} → ?`});grid.appendChild(cell)})});
document.querySelectorAll('.end-times button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.end-times button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));